package device

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// Inputs come from the standalone document, generated by an independent
// implementation of its pseudocode. Exercise the actual deployed Noise parser.
func TestStandaloneProtocolNoiseVectors(t *testing.T) {
	document, err := os.ReadFile("../../../docs/WG-QUIC-PROTOCOL.md")
	if err != nil {
		t.Fatal(err)
	}
	var vectors struct{ Salamander, Noise map[string]string }
	document = bytes.ReplaceAll(document, []byte("\r\n"), []byte("\n"))
	block := bytes.SplitN(document, []byte("```json\n"), 2)
	if len(block) != 2 {
		t.Fatal("missing protocol vectors")
	}
	if err := json.Unmarshal(bytes.SplitN(block[1], []byte("\n```"), 2)[0], &vectors); err != nil {
		t.Fatal(err)
	}
	decode := func(s string) []byte {
		b, e := hex.DecodeString(s)
		if e != nil {
			t.Fatal(e)
		}
		return b
	}
	a, b := randDevice(t), randDevice(t)
	defer a.Close()
	defer b.Close()
	var sa, sb NoisePrivateKey
	copy(sa[:], decode(vectors.Salamander["private_a"]))
	copy(sb[:], decode(vectors.Salamander["private_b"]))
	assertNil(t, a.SetPrivateKey(sa))
	assertNil(t, b.SetPrivateKey(sb))
	pa, err := a.NewPeer(sb.publicKey())
	assertNil(t, err)
	pb, err := b.NewPeer(sa.publicKey())
	assertNil(t, err)
	copy(pa.handshake.presharedKey[:], decode(vectors.Salamander["psk"]))
	copy(pb.handshake.presharedKey[:], decode(vectors.Salamander["psk"]))
	pa.Start()
	pb.Start()
	initBytes := decode(vectors.Noise["initiation"])
	responseBytes := decode(vectors.Noise["response"])
	var checker CookieChecker
	checker.Init(sb.publicKey())
	if !checker.CheckMAC1(initBytes) {
		t.Fatal("initiation MAC1")
	}
	checker.Init(sa.publicKey())
	if !checker.CheckMAC1(responseBytes) {
		t.Fatal("response MAC1")
	}
	var initiation MessageInitiation
	assertNil(t, initiation.unmarshal(initBytes))
	if b.ConsumeMessageInitiation(&initiation) != pb {
		t.Fatal("independent initiation rejected")
	}
	assertEqual(t, pb.handshake.chainKey[:], decode(vectors.Noise["chain_after_initiation"]))
	assertEqual(t, pb.handshake.hash[:], decode(vectors.Noise["hash_after_initiation"]))
	// Seed the initiator with the same post-initiation state and fixed ephemeral
	// input; production CreateMessageInitiation intentionally uses randomness.
	pa.handshake.mutex.Lock()
	pa.handshake.chainKey = pb.handshake.chainKey
	pa.handshake.hash = pb.handshake.hash
	copy(pa.handshake.localEphemeral[:], decode(vectors.Noise["ephemeral_private_a"]))
	pa.handshake.localIndex = initiation.Sender
	pa.handshake.state = handshakeInitiationCreated
	pa.handshake.mutex.Unlock()
	a.indexTable.Lock()
	a.indexTable.table[initiation.Sender] = IndexTableEntry{peer: pa, handshake: &pa.handshake}
	a.indexTable.Unlock()
	var response MessageResponse
	assertNil(t, response.unmarshal(responseBytes))
	if a.ConsumeMessageResponse(&response) != pa {
		t.Fatal("independent response rejected")
	}
	assertEqual(t, pa.handshake.chainKey[:], decode(vectors.Noise["chain_final"]))
	assertEqual(t, pa.handshake.hash[:], decode(vectors.Noise["hash_final"]))
	assertNil(t, pa.BeginSymmetricSession())
	keepalive := decode(vectors.Noise["keepalive"])
	encrypted := pa.keypairs.current.send.Seal(nil, make([]byte, 12), nil, nil)
	assertEqual(t, encrypted, keepalive[16:])
	if b.ConsumeMessageInitiation(&initiation) != nil {
		t.Fatal("replayed initiation accepted")
	}
}
